// Package config reads shyd's environment.
package config

import (
	"fmt"
	"net/url"
	"os"
	"strconv"
	"strings"
)

const (
	defaultAddr    = ":8080"
	defaultDB      = "shy.db"
	defaultIngest  = "https://ingest.neatlogs.com"
	defaultBody    = 8 << 20
	maxBody        = 50 << 20
)

// Config is everything the process needs, with secrets left as the operator set them.
type Config struct {
	Addr              string
	DBPath            string
	PublicURL         string
	NeatlogsAPIKey    string
	NeatlogsProject   string
	NeatlogsIngestURL string
	CookieSecure      bool
	TrustProxy        bool
	BodyLimit         int64
}

// FromEnv loads configuration. A write key (nlw_…) without a project name is an error.
// An empty Neatlogs key is allowed: traces are stored and not forwarded.
func FromEnv() (Config, error) {
	cfg := Config{
		Addr:              env("SHY_HTTP_ADDR", defaultAddr),
		DBPath:            env("SHY_DB_PATH", defaultDB),
		NeatlogsAPIKey:    strings.TrimSpace(os.Getenv("SHY_NEATLOGS_API_KEY")),
		NeatlogsProject:   strings.TrimSpace(os.Getenv("SHY_NEATLOGS_PROJECT_NAME")),
		NeatlogsIngestURL: env("SHY_NEATLOGS_INGEST_URL", defaultIngest),
		CookieSecure:      envBool("SHY_COOKIE_SECURE"),
		TrustProxy:        envBool("SHY_TRUST_PROXY"),
	}
	var err error
	cfg.BodyLimit, err = envInt("SHY_BODY_LIMIT", defaultBody, maxBody)
	if err != nil {
		return Config{}, err
	}
	public := strings.TrimSpace(os.Getenv("SHY_PUBLIC_URL"))
	if public == "" {
		public = defaultPublic(cfg.Addr)
	}
	cfg.PublicURL, err = checkBaseURL(public, "SHY_PUBLIC_URL")
	if err != nil {
		return Config{}, err
	}
	cfg.NeatlogsIngestURL, err = checkBaseURL(cfg.NeatlogsIngestURL, "SHY_NEATLOGS_INGEST_URL")
	if err != nil {
		return Config{}, err
	}
	if strings.HasPrefix(cfg.NeatlogsAPIKey, "nlw_") && cfg.NeatlogsProject == "" {
		return Config{}, fmt.Errorf("SHY_NEATLOGS_PROJECT_NAME is required when SHY_NEATLOGS_API_KEY is a write key (nlw_)")
	}
	return cfg, nil
}

func defaultPublic(addr string) string {
	host := addr
	if strings.HasPrefix(host, ":") {
		host = "127.0.0.1" + host
	}
	return "http://" + host
}

func checkBaseURL(raw, name string) (string, error) {
	u, err := url.Parse(raw)
	if err != nil || u.Host == "" || (u.Scheme != "http" && u.Scheme != "https") || u.User != nil {
		return "", fmt.Errorf("%s must be an http(s) URL", name)
	}
	if (u.Path != "" && u.Path != "/") || u.RawQuery != "" || u.Fragment != "" {
		return "", fmt.Errorf("%s must not include a path, query, or fragment", name)
	}
	return strings.TrimRight(raw, "/"), nil
}

func env(name, fallback string) string {
	v := strings.TrimSpace(os.Getenv(name))
	if v == "" {
		return fallback
	}
	return v
}

func envBool(name string) bool {
	switch strings.ToLower(strings.TrimSpace(os.Getenv(name))) {
	case "1", "true", "yes", "on":
		return true
	default:
		return false
	}
}

func envInt(name string, fallback, max int64) (int64, error) {
	v := strings.TrimSpace(os.Getenv(name))
	if v == "" {
		return fallback, nil
	}
	n, err := strconv.ParseInt(v, 10, 64)
	if err != nil || n < 1024 {
		return 0, fmt.Errorf("%s must be a byte count of at least 1024", name)
	}
	if n > max {
		return 0, fmt.Errorf("%s must be at most %d", name, max)
	}
	return n, nil
}

// Package trace prepares a shy trace for storage and for Neatlogs.
//
// The body is the nested JSON tree shy already posts to /v1/trace.
// Prepare keeps that shape, stamps the account on as the end user, and
// removes client-chosen project and span ids so the server's Neatlogs
// key is what selects the project.
package trace

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"unicode/utf8"
)

const (
	previewLen = 240
	maxName    = 200
	maxNodes   = 10000
	maxDepth   = 64
)

var (
	errInvalid = errors.New("invalid JSON")
	errShape   = errors.New("trace must be a JSON object")
	errName    = errors.New("trace name is required")
	errTooBig  = errors.New("trace has too many spans")
	errTooDeep = errors.New("trace is nested too deeply")
	errKids    = errors.New("children must be an array")
)

// Meta is the part the database indexes. The full tree is stored separately.
type Meta struct {
	Workflow          string
	Status            string
	SessionID         string
	InputPreview      string
	OutputPreview     string
	PromptTokens      int64
	CompletionTokens  int64
	Spans             int
}

// Node is one span for the dashboard tree.
type Node struct {
	Name     string
	Kind     string
	Status   string
	Meta     string
	Children []Node
}

// Prepare validates raw, stamps accountNumber onto the root, and returns the
// JSON that should be stored and forwarded. writeKey selects whether project
// is set from projectName (nlw_ keys) or removed (project keys).
func Prepare(raw []byte, accountNumber string, installID int64, installName, projectName string, writeKey bool) ([]byte, Meta, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var root any
	if err := dec.Decode(&root); err != nil || dec.More() {
		return nil, Meta{}, errInvalid
	}
	obj, ok := root.(map[string]any)
	if !ok {
		return nil, Meta{}, errShape
	}
	name, _ := obj["name"].(string)
	name = strings.TrimSpace(name)
	if name == "" {
		return nil, Meta{}, errName
	}
	name = clip(name, maxName)
	obj["name"] = name

	stripIDs(obj)
	if writeKey {
		obj["project"] = projectName
	} else {
		delete(obj, "project")
	}
	if kind, _ := obj["kind"].(string); strings.TrimSpace(kind) == "" {
		obj["kind"] = "WORKFLOW"
	}

	attrs, ok := obj["attributes"].(map[string]any)
	if !ok {
		attrs = map[string]any{}
		obj["attributes"] = attrs
	}
	session, _ := attrs["neatlogs.session.id"].(string)
	attrs["neatlogs.end_user.id"] = accountNumber
	metaJSON, err := json.Marshal(map[string]any{
		"install_id": installID,
		"install":    installName,
	})
	if err != nil {
		return nil, Meta{}, err
	}
	// Neatlogs wants this value as a JSON string, not an object.
	attrs["neatlogs.end_user.metadata"] = string(metaJSON)

	status := "OK"
	if s, ok := obj["status"].(string); ok && strings.EqualFold(strings.TrimSpace(s), "ERROR") {
		status = "ERROR"
	}
	obj["status"] = status

	var st stats
	if err := walk(obj, &st, 0); err != nil {
		return nil, Meta{}, err
	}
	out, err := json.Marshal(obj)
	if err != nil {
		return nil, Meta{}, err
	}
	return out, Meta{
		Workflow:         name,
		Status:           status,
		SessionID:        clip(session, maxName),
		InputPreview:     preview(obj["input"]),
		OutputPreview:    preview(obj["output"]),
		PromptTokens:     st.prompt,
		CompletionTokens: st.completion,
		Spans:            st.spans,
	}, nil
}

// Tree parses a stored payload into a span tree for the dashboard.
func Tree(payload []byte) (Node, error) {
	dec := json.NewDecoder(bytes.NewReader(payload))
	dec.UseNumber()
	var v any
	if err := dec.Decode(&v); err != nil {
		return Node{}, err
	}
	n, ok := toNode(v, 0)
	if !ok {
		return Node{}, errShape
	}
	return n, nil
}

func stripIDs(v any) {
	m, ok := v.(map[string]any)
	if !ok {
		return
	}
	delete(m, "trace_id")
	delete(m, "span_id")
	delete(m, "parent_span_id")
	kids, _ := m["children"].([]any)
	for _, c := range kids {
		stripIDs(c)
	}
}

type stats struct {
	spans      int
	prompt     int64
	completion int64
}

func walk(v any, st *stats, depth int) error {
	m, ok := v.(map[string]any)
	if !ok {
		return nil
	}
	if st.spans >= maxNodes {
		return errTooBig
	}
	if depth > maxDepth {
		return errTooDeep
	}
	st.spans++
	if kind, _ := m["kind"].(string); strings.EqualFold(kind, "LLM") {
		if tok, ok := m["tokens"].(map[string]any); ok {
			st.prompt += integer(tok["prompt"])
			st.completion += integer(tok["completion"])
		}
	}
	kids, exists := m["children"]
	if !exists || kids == nil {
		return nil
	}
	list, ok := kids.([]any)
	if !ok {
		return errKids
	}
	for _, c := range list {
		if err := walk(c, st, depth+1); err != nil {
			return err
		}
	}
	return nil
}

func toNode(v any, depth int) (Node, bool) {
	if depth > maxDepth {
		return Node{Name: "…", Kind: "SPAN"}, true
	}
	m, ok := v.(map[string]any)
	if !ok {
		return Node{}, false
	}
	n := Node{
		Name:   str(m["name"]),
		Kind:   str(m["kind"]),
		Status: str(m["status"]),
	}
	if n.Kind == "" {
		n.Kind = "SPAN"
	}
	var bits []string
	if model := str(m["model"]); model != "" {
		bits = append(bits, model)
	}
	if tool := str(m["tool_name"]); tool != "" {
		bits = append(bits, tool)
	}
	if d := integer(m["duration_ms"]); d > 0 {
		bits = append(bits, fmt.Sprintf("%dms", d))
	}
	if msg := str(m["error"]); msg != "" {
		bits = append(bits, clip(msg, 160))
	}
	n.Meta = strings.Join(bits, " · ")
	if kids, ok := m["children"].([]any); ok {
		for _, c := range kids {
			if child, ok := toNode(c, depth+1); ok {
				n.Children = append(n.Children, child)
			}
		}
	}
	return n, true
}

func preview(v any) string {
	if v == nil {
		return ""
	}
	s, ok := v.(string)
	if !ok {
		b, err := json.Marshal(v)
		if err != nil {
			return ""
		}
		s = string(b)
	}
	return clip(s, previewLen)
}

func str(v any) string {
	s, _ := v.(string)
	return strings.TrimSpace(s)
}

func integer(v any) int64 {
	switch n := v.(type) {
	case json.Number:
		if i, err := n.Int64(); err == nil {
			return i
		}
		f, err := n.Float64()
		if err != nil {
			return 0
		}
		return int64(f)
	case float64:
		return int64(n)
	default:
		return 0
	}
}

func clip(s string, n int) string {
	if utf8.RuneCountInString(s) <= n {
		return s
	}
	r := []rune(s)
	return string(r[:n]) + "…"
}

// Package neatlogs forwards one trace tree to Neatlogs HTTP ingest.
package neatlogs

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strings"

	"shy/server/internal/version"
)

// ErrNotConfigured means the server has no Neatlogs key. The trace is stored
// and not forwarded.
var ErrNotConfigured = errors.New("neatlogs is not configured")

// Forwarder sends a prepared trace body.
type Forwarder interface {
	Forward(ctx context.Context, body []byte) (traceID string, spans int, err error)
}

// Disabled stores traces locally and does not call Neatlogs.
type Disabled struct{}

func (Disabled) Forward(context.Context, []byte) (string, int, error) {
	return "", 0, ErrNotConfigured
}

// StatusError is a non-2xx response or a 2xx body with no trace id.
type StatusError struct {
	Code int
	Body string
}

func (e *StatusError) Error() string {
	msg := strings.TrimSpace(e.Body)
	if len(msg) > 300 {
		msg = msg[:300]
	}
	if msg == "" {
		return fmt.Sprintf("neatlogs http %d", e.Code)
	}
	return fmt.Sprintf("neatlogs http %d: %s", e.Code, msg)
}

// Client posts to {IngestURL}/v1/trace with the server's key.
type Client struct {
	IngestURL string
	APIKey    string
	HTTP      *http.Client
}

func (c *Client) Forward(ctx context.Context, body []byte) (string, int, error) {
	endpoint := strings.TrimRight(c.IngestURL, "/") + "/v1/trace"
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
	if err != nil {
		return "", 0, err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("x-api-key", c.APIKey)
	req.Header.Set("User-Agent", "shyd/"+version.Version)

	resp, err := c.httpClient().Do(req)
	if err != nil {
		return "", 0, err
	}
	defer resp.Body.Close()
	buf, err := io.ReadAll(io.LimitReader(resp.Body, 8192))
	if err != nil {
		return "", 0, err
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return "", 0, &StatusError{Code: resp.StatusCode, Body: string(buf)}
	}
	var parsed struct {
		TraceID string `json:"trace_id"`
		Spans   int    `json:"spans"`
	}
	_ = json.Unmarshal(buf, &parsed)
	if parsed.TraceID == "" {
		return "", 0, &StatusError{Code: resp.StatusCode, Body: "response had no trace_id"}
	}
	return parsed.TraceID, parsed.Spans, nil
}

func (c *Client) httpClient() *http.Client {
	if c.HTTP != nil {
		return c.HTTP
	}
	return &http.Client{
		Timeout: 20 * 1e9, // filled in below to avoid a time import cycle in this sketch
	}
}

