type view struct {
	Title         string
	Version       string
	CSRF          string
	FormToken     string
	PublicURL     string
	LoginError    string
	RegisterError string
	NumberRaw     string
	NumberPretty  string
	NewAccount    bool
	Installs      []installView
	Reveal        *revealView
	Traces        []traceView
	Detail        *detailView
}

type installView struct {
	ID       int64
	Name     string
	Prefix   string
	Created  string
	LastSeen string
	Revoked  bool
}

type revealView struct {
	Name string
	Key  string
	Env  string
}

type traceView struct {
	ID       int64
	When     string
	Workflow string
	Status   string
	Tokens   string
	Install  string
	Forward  string
}

type detailView struct {
	When         string
	Workflow     string
	Status       string
	Session      string
	Install      string
	Forward      string
	ForwardError string
	NeatlogsID   string
	Prompt       int64
	Completion   int64
	SpanCount    int
	Input        string
	Output       string
	Spans        []trace.Node
	Raw          string
}

func buildView(cfg config.Config, sess store.Session, flash store.Flash, installs []store.Install, traces []store.Trace) view {
	public := strings.TrimRight(cfg.PublicURL, "/")
	v := view{
		Title:        "shy",
		CSRF:         sess.CSRF,
		PublicURL:    public,
		NumberRaw:    sess.Number,
		NumberPretty: prettyNumber(sess.Number),
		NewAccount:   flash.NewAccount,
	}
	for _, in := range installs {
		v.Installs = append(v.Installs, installView{
			ID:       in.ID,
			Name:     in.Name,
			Prefix:   in.KeyPrefix,
			Created:  fmtTime(in.CreatedAt),
			LastSeen: fmtTime(in.LastSeenAt),
			Revoked:  in.RevokedAt != "",
		})
	}
	for _, tr := range traces {
		v.Traces = append(v.Traces, traceView{
			ID:       tr.ID,
			When:     fmtTime(tr.ReceivedAt),
			Workflow: tr.Workflow,
			Status:   tr.Status,
			Tokens:   fmt.Sprintf("%d in · %d out", tr.PromptTokens, tr.CompletionTokens),
			Install:  tr.InstallName,
			Forward:  tr.ForwardStatus,
		})
	}
	if flash.Key != "" {
		name := flash.InstallName
		if name == "" {
			name = "install"
		}
		v.Reveal = &revealView{
			Name: name,
			Key:  flash.Key,
			Env:  "export NEATLOGS_INGEST_URL=" + public + "\nexport NEATLOGS_API_KEY=" + flash.Key,
		}
	}
	return v
}

func toDetail(tr store.Trace) *detailView {
	session := tr.SessionID
	if session == "" {
		session = "—"
	}
	nid := tr.NeatlogsTraceID
	if nid == "" {
		nid = "—"
	}
	d := &detailView{
		When:         fmtTime(tr.ReceivedAt),
		Workflow:     tr.Workflow,
		Status:       tr.Status,
		Session:      session,
		Install:      tr.InstallName,
		Forward:      tr.ForwardStatus,
		ForwardError: tr.ForwardError,
		NeatlogsID:   nid,
		Prompt:       tr.PromptTokens,
		Completion:   tr.CompletionTokens,
		SpanCount:    tr.SpanCount,
		Input:        tr.InputPreview,
		Output:       tr.OutputPreview,
		Raw:          clipRaw(tr.Payload, 65536),
	}
	if node, err := trace.Tree([]byte(tr.Payload)); err == nil {
		d.Spans = []trace.Node{node}
	}
	return d
}

func prettyNumber(n string) string {
	if len(n) != 16 {
		return n
	}
	return n[0:4] + " " + n[4:8] + " " + n[8:12] + " " + n[12:16]
}

func normalizeNumber(s string) (string, bool) {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case ' ', '-', '\t', '\n', '\r':
			continue
		}
		if r < '0' || r > '9' {
			return "", false
		}
		b.WriteRune(r)
	}
	if b.Len() != 16 {
		return "", false
	}
	return b.String(), true
}

func fmtTime(s string) string {
	if s == "" {
		return "—"
	}
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return s
	}
	return t.UTC().Format("2006-01-02 15:04")
}

func clipRaw(s string, n int) string {
	if len(s) <= n {
		return s
	}
	for n > 0 && !utf8.RuneStart(s[n]) {
		n--
	}
	return s[:n] + "\n… truncated"
}

func clipErr(s string) string {
	const n = 500
	if len(s) <= n {
		return s
	}
	for n > 0 && !utf8.RuneStart(s[n]) {
		n--
	}
	return s[:n]
}

package httpapi

import (
	"errors"
	"log/slog"
	"net"
	"net/http"
	"strconv"
	"strings"

	"shy/server/internal/store"
)

func (s *Server) health(w http.ResponseWriter, r *http.Request) {
	if err := s.store.Ping(r.Context()); err != nil {
		http.Error(w, "db", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	_, _ = w.Write([]byte("ok\n"))
}

func (s *Server) home(w http.ResponseWriter, r *http.Request) {
	sess, raw, ok := s.session(w, r)
	if !ok {
		s.gate(w, r, "", "", http.StatusOK)
		return
	}
	flash, err := s.store.TakeFlash(r.Context(), raw)
	if errors.Is(err, store.ErrNotFound) {
		s.clearSessionCookie(w)
		s.gate(w, r, "", "", http.StatusOK)
		return
	}
	if err != nil {
		s.fail(w, err)
		return
	}
	v, err := s.dashboardView(r, sess, flash)
	if err != nil {
		s.fail(w, err)
		return
	}
	s.render(w, "dashboard", v, http.StatusOK)
}

func (s *Server) gate(w http.ResponseWriter, r *http.Request, loginErr, registerErr string, status int) {
	if status == 0 {
		status = http.StatusOK
	}
	s.render(w, "gate", view{
		Title:         "shy",
		FormToken:     s.formToken(w, r),
		LoginError:    loginErr,
		RegisterError: registerErr,
	}, status)
}

func (s *Server) createAccount(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, 1<<16)
	if !s.register.allow(clientIP(r, s.cfg.TrustProxy)) {
		s.gate(w, r, "", "Too many new accounts from this network. Try again later.", http.StatusTooManyRequests)
		return
	}
	if !s.formOK(r) {
		http.Error(w, "Form expired. Reload and try again.", http.StatusForbidden)
		return
	}
	acc, raw, err := s.store.CreateAccount(r.Context())
	if err != nil {
		s.fail(w, err)
		return
	}
	if err := s.store.SetFlash(r.Context(), raw, store.Flash{NewAccount: true}); err != nil {
		slog.Error("flash", "err", err, "account", acc.ID)
	}
	s.setSessionCookie(w, raw)
	slog.Info("account created", "account", acc.ID)
	http.Redirect(w, r, "/", http.StatusSeeOther)
}

func (s *Server) login(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, 1<<16)
	if !s.login.allow(clientIP(r, s.cfg.TrustProxy)) {
		s.gate(w, r, "Too many sign-in attempts. Wait a few minutes.", "", http.StatusTooManyRequests)
		return
	}
	if !s.formOK(r) {
		http.Error(w, "Form expired. Reload and try again.", http.StatusForbidden)
		return
	}
	number, ok := normalizeNumber(r.FormValue("number"))
	if !ok {
		s.gate(w, r, "Enter the 16-digit account number.", "", http.StatusUnauthorized)
		return
	}
	acc, err := s.store.AccountByNumber(r.Context(), number)
	if err != nil || acc.Status != "active" {
		s.gate(w, r, "No account uses that number.", "", http.StatusUnauthorized)
		return
	}
	raw, err := s.store.CreateSession(r.Context(), acc.ID)
	if err != nil {
		s.fail(w, err)
		return
	}
	s.setSessionCookie(w, raw)
	http.Redirect(w, r, "/", http.StatusSeeOther)
}

func (s *Server) logout(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, 1<<16)
	sess, raw, ok := s.session(w, r)
	if ok {
		if !s.csrfOK(r, sess) {
			http.Error(w, "Form expired. Reload and try again.", http.StatusForbidden)
			return
		}
		if err := s.store.DeleteSession(r.Context(), raw); err != nil {
			slog.Error("logout", "err", err)
		}
	}
	s.clearSessionCookie(w)
	http.Redirect(w, r, "/", http.StatusSeeOther)
}

func (s *Server) createInstall(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, 1<<16)
	sess, raw, ok := s.session(w, r)
	if !ok {
		http.Redirect(w, r, "/", http.StatusSeeOther)
		return
	}
	if !s.csrfOK(r, sess) {
		http.Error(w, "Form expired. Reload and try again.", http.StatusForbidden)
		return
	}
	inst, key, err := s.store.CreateInstall(r.Context(), sess.AccountID, r.FormValue("name"))
	if err != nil {
		s.fail(w, err)
		return
	}
	if err := s.store.SetFlash(r.Context(), raw, store.Flash{Key: key, InstallName: inst.Name}); err != nil {
		s.fail(w, err)
		return
	}
	slog.Info("install created", "account", sess.AccountID, "install", inst.ID)
	http.Redirect(w, r, "/", http.StatusSeeOther)
}

func (s *Server) revokeInstall(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, 1<<16)
	sess, _, ok := s.session(w, r)
	if !ok {
		http.Redirect(w, r, "/", http.StatusSeeOther)
		return
	}
	if !s.csrfOK(r, sess) {
		http.Error(w, "Form expired. Reload and try again.", http.StatusForbidden)
		return
	}
	id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
	if err != nil || id < 1 {
		http.NotFound(w, r)
		return
	}
	if err := s.store.RevokeInstall(r.Context(), sess.AccountID, id); errors.Is(err, store.ErrNotFound) {
		http.NotFound(w, r)
		return
	} else if err != nil {
		s.fail(w, err)
		return
	}
	slog.Info("install revoked", "account", sess.AccountID, "install", id)
	http.Redirect(w, r, "/", http.StatusSeeOther)
}

func (s *Server) traces(w http.ResponseWriter, r *http.Request) {
	sess, _, ok := s.session(w, r)
	if !ok {
		if hx(r) {
			w.Header().Set("HX-Redirect", "/")
			w.WriteHeader(http.StatusOK)
			return
		}
		http.Redirect(w, r, "/", http.StatusSeeOther)
		return
	}
	list, err := s.store.ListTraces(r.Context(), sess.AccountID, 50)
	if err != nil {
		s.fail(w, err)
		return
	}
	if hx(r) {
		v := view{CSRF: sess.CSRF}
		for _, tr := range list {
			v.Traces = append(v.Traces, traceRow(tr))
		}
		s.render(w, "traces", v, http.StatusOK)
		return
	}
	v, err := s.dashboardView(r, sess, store.Flash{})
	if err != nil {
		s.fail(w, err)
		return
	}
	s.render(w, "dashboard", v, http.StatusOK)
}

func (s *Server) traceDetail(w http.ResponseWriter, r *http.Request) {
	sess, _, ok := s.session(w, r)
	if !ok {
		if hx(r) {
			w.Header().Set("HX-Redirect", "/")
			w.WriteHeader(http.StatusOK)
			return
		}
		http.Redirect(w, r, "/", http.StatusSeeOther)
		return
	}
	id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
	if err != nil || id < 1 {
		http.NotFound(w, r)
		return
	}
	tr, err := s.store.Trace(r.Context(), sess.AccountID, id)
	if errors.Is(err, store.ErrNotFound) {
		http.NotFound(w, r)
		return
	}
	if err != nil {
		s.fail(w, err)
		return
	}
	if hx(r) {
		s.render(w, "detail", view{CSRF: sess.CSRF, Detail: toDetail(tr)}, http.StatusOK)
		return
	}
	v, err := s.dashboardView(r, sess, store.Flash{})
	if err != nil {
		s.fail(w, err)
		return
	}
	v.Detail = toDetail(tr)
	v.Title = tr.Workflow
	s.render(w, "dashboard", v, http.StatusOK)
}

func (s *Server) dashboardView(r *http.Request, sess store.Session, flash store.Flash) (view, error) {
	installs, err := s.store.ListInstalls(r.Context(), sess.AccountID)
	if err != nil {
		return view{}, err
	}
	traces, err := s.store.ListTraces(r.Context(), sess.AccountID, 50)
	if err != nil {
		return view{}, err
	}
	return buildView(s.cfg, sess, flash, installs, traces), nil
}

func traceRow(tr store.Trace) traceView {
	return buildView(config.Config{}, store.Session{}, store.Flash{}, nil, []store.Trace{tr}).Traces[0]
}

func clientIP(r *http.Request, trust bool) string {
	if trust {
		if xff := r.Header.Get("X-Forwarded-For"); xff != "" {
			first := strings.TrimSpace(strings.Split(xff, ",")[0])
			if first != "" {
				return first
			}
		}
	}
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		return r.RemoteAddr
	}
	return host
}

package httpapi

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"net/http"
	"strings"
	"time"

	"shy/server/internal/neatlogs"
	"shy/server/internal/store"
	"shy/server/internal/trace"
)

func (s *Server) ingest(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Cache-Control", "no-store")
	key := apiKey(r)
	if key == "" {
		writeJSON(w, http.StatusUnauthorized, map[string]any{"success": false, "error": "invalid api key"})
		return
	}
	inst, acc, err := s.store.InstallByKey(r.Context(), key)
	if err != nil {
		writeJSON(w, http.StatusUnauthorized, map[string]any{"success": false, "error": "invalid api key"})
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, s.cfg.BodyLimit)
	body, err := io.ReadAll(r.Body)
	if err != nil {
		var tooBig *http.MaxBytesError
		if errors.As(err, &tooBig) {
			writeJSON(w, http.StatusRequestEntityTooLarge, map[string]any{"success": false, "error": "trace is too large"})
			return
		}
		writeJSON(w, http.StatusBadRequest, map[string]any{"success": false, "error": "invalid body"})
		return
	}
	writeKey := strings.HasPrefix(s.cfg.NeatlogsAPIKey, "nlw_")
	patched, meta, err := trace.Prepare(body, acc.Number, inst.ID, inst.Name, s.cfg.NeatlogsProject, writeKey)
	if err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]any{"success": false, "error": err.Error()})
		return
	}
	id, err := s.store.InsertTrace(r.Context(), store.NewTrace{
		AccountID:        acc.ID,
		InstallID:        inst.ID,
		Workflow:         meta.Workflow,
		Status:           meta.Status,
		SessionID:        meta.SessionID,
		InputPreview:     meta.InputPreview,
		OutputPreview:    meta.OutputPreview,
		PromptTokens:     meta.PromptTokens,
		CompletionTokens: meta.CompletionTokens,
		SpanCount:        meta.Spans,
		Payload:          string(patched),
	})
	if err != nil {
		s.fail(w, err)
		return
	}
	if err := s.store.TouchInstall(r.Context(), inst.ID); err != nil {
		slog.Error("touch install", "err", err, "install", inst.ID)
	}

	if errors.Is(forwardErr(s.forward), neatlogs.ErrNotConfigured) || isDisabled(s.forward) {
		if err := s.store.MarkForward(r.Context(), id, "skipped", "", ""); err != nil {
			slog.Error("mark skipped", "err", err, "trace", id)
		}
		slog.Info("trace stored", "account", acc.ID, "install", inst.ID, "workflow", meta.Workflow, "forward", "skipped")
		writeJSON(w, http.StatusOK, map[string]any{"success": true, "stored": true, "forwarded": false})
		return
	}

	ctx, cancel := context.WithTimeout(context.WithoutCancel(r.Context()), 20*time.Second)
	defer cancel()
	neatID, spans, err := s.forward.Forward(ctx, patched)
	if err != nil {
		if errors.Is(err, neatlogs.ErrNotConfigured) {
			if merr := s.store.MarkForward(r.Context(), id, "skipped", "", ""); merr != nil {
				slog.Error("mark skipped", "err", merr, "trace", id)
			}
			writeJSON(w, http.StatusOK, map[string]any{"success": true, "stored": true, "forwarded": false})
			return
		}
		msg := clipErr(err.Error())
		if merr := s.store.MarkForward(r.Context(), id, "failed", "", msg); merr != nil {
			slog.Error("mark failed", "err", merr, "trace", id)
		}
		slog.Warn("forward failed", "account", acc.ID, "install", inst.ID, "workflow", meta.Workflow, "err", msg)
		// Stored either way. 502 so shy prints its ingest warning. shy does not retry.
		writeJSON(w, http.StatusBadGateway, map[string]any{
			"success": false, "stored": true, "error": "forwarding to neatlogs failed",
		})
		return
	}
	if spans == 0 {
		spans = meta.Spans
	}
	if err := s.store.MarkForward(r.Context(), id, "sent", neatID, ""); err != nil {
		slog.Error("mark sent", "err", err, "trace", id)
	}
	slog.Info("trace stored", "account", acc.ID, "install", inst.ID, "workflow", meta.Workflow, "forward", "sent", "neatlogs_trace_id", neatID)
	writeJSON(w, http.StatusOK, map[string]any{
		"success": true, "stored": true, "forwarded": true, "trace_id": neatID, "spans": spans,
	})
}

func isDisabled(f neatlogs.Forwarder) bool {
	_, ok := f.(neatlogs.Disabled)
	return ok
}

func forwardErr(neatlogs.Forwarder) error { return nil }

func apiKey(r *http.Request) string {
	var bearer string
	h := r.Header.Get("Authorization")
	if len(h) >= 7 && strings.EqualFold(h[:7], "bearer ") {
		bearer = strings.TrimSpace(h[7:])
	}
	x := strings.TrimSpace(r.Header.Get("X-Api-Key"))
	if bearer != "" && x != "" && bearer != x {
		return ""
	}
	key := bearer
	if key == "" {
		key = x
	}
	if len(key) < 8 || len(key) > 200 {
		return ""
	}
	return key
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

