.muted { color: var(--muted); }
.bad { color: var(--bad); }
.ok { color: var(--green); }
.wait { color: var(--wait); }
.mono, .digits, .secret, .kind { font-family: var(--mono); }

.digits {
  letter-spacing: 0.08em;
  user-select: all;
}

a { color: inherit; }
#traces a { text-underline-offset: 2px; }

.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-top: 18px;
}

.card, .banner, .detail {
  background: var(--paper);
  border: 1px solid var(--line);
  padding: 16px 16px 18px;
}

.banner { border-color: var(--green); margin-bottom: 16px; }
.banner .digits { font-size: 1.8rem; margin: 8px 0 12px; }

.bar {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 18px;
}

.bar .digits {
  margin: 0 0 0 auto;
  font-size: 0.95rem;
}

section + section, #detail { margin-top: 16px; }
#detail:empty { display: none; }

.reveal {
  border: 1px solid var(--green);
  background: #f3faf6;
  padding: 12px 14px;
  margin: 0 0 14px;
}

.secret {
  font-size: 14px;
  word-break: break-all;
}

button, .btn {
  font: inherit;
  cursor: pointer;
  border: 0;
  border-radius: 2px;
  padding: 8px 12px;
  background: var(--ink);
  color: #f6f1e6;
}

button.primary { background: var(--green); color: var(--green-ink); }
button.primary:hover { background: #0c5846; }
button.ghost {
  background: transparent;
  color: var(--ink);
  border: 1px solid #c9bfb0;
}
button.ghost:hover { border-color: var(--ink); }
button:disabled { opacity: 0.6; }

:focus-visible {
  outline: 2px solid var(--green);
  outline-offset: 2px;
}

form.inline { display: inline; margin: 0; }
form.row {
  display: flex;
  gap: 8px;
  align-items: flex-end;
  margin: 0 0 14px;
}
form.row label { flex: 1; }
td form { margin: 0; }

label {
  display: block;
  font-size: 13px;
  color: var(--muted);
  margin-bottom: 10px;
}

input[name="number"], input[name="name"] {
  display: block;
  width: 100%;
  margin-top: 6px;
  padding: 8px 10px;
  border: 1px solid #c9bfb0;
  border-radius: 2px;
  background: #fff;
  color: inherit;
  font: inherit;
}

input[name="number"] {
  font-family: var(--mono);
  letter-spacing: 0.08em;
}

table { width: 100%; border-collapse: collapse; }
th {
  text-align: left;
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 600;
  padding: 0 12px 8px 0;
}
td {
  padding: 8px 12px 8px 0;
  border-top: 1px solid #e4dccf;
  vertical-align: baseline;
}

ul.spans { list-style: none; padding: 0; margin: 8px 0 0; }
ul.spans ul {
  margin: 4px 0 4px 8px;
  padding-left: 12px;
  border-left: 1px solid var(--line);
}
ul.spans li { margin: 4px 0; }
.kind {
  font-size: 11px;
  letter-spacing: 0.06em;
  color: var(--green);
  margin-right: 6px;
