  word-break: break-word;
}
pre.env, details pre {
  background: var(--ink);
  color: #f6f1e6;
  padding: 12px;
  margin: 8px 0;
  max-height: 320px;
  overflow: auto;
}
pre.preview {
  background: #f6f1e6;
  border: 1px solid #e4dccf;
  padding: 10px;
  margin: 6px 0 0;
