.foot {
  margin-top: 28px;
  color: var(--muted);
  font-size: 13px;
}

#traces.htmx-request { opacity: 0.55; }

@media (max-width: 720px) {
  .grid { grid-template-columns: 1fr; }
  .bar { flex-wrap: wrap; }
  .bar .digits { margin-left: 0; }
  .banner .digits { font-size: 1.25rem; letter-spacing: 0.04em; }
  form.row { flex-direction: column; align-items: stretch; }
}

(function () {
  var csrf = document.querySelector('meta[name="csrf"]');
  if (csrf && csrf.content) {
    document.body.addEventListener("htmx:configRequest", function (ev) {
      if (ev.detail.verb && ev.detail.verb !== "get") {
        ev.detail.headers["X-Shy-CSRF"] = csrf.content;
      }
    });
  }

  document.addEventListener("click", function (ev) {
    var btn = ev.target.closest("[data-copy]");
    if (!btn) return;
    var text = btn.getAttribute("data-copy") || "";
    var prev = btn.textContent;
    var done = function () {
      btn.textContent = "Copied";
      setTimeout(function () { btn.textContent = prev; }, 1200);
    };
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(done, function () {
        fallback(text);
        done();
      });
      return;
    }
    fallback(text);
    done();
  });

  function fallback(text) {
    var ta = document.createElement("textarea");
    ta.value = text;
    ta.setAttribute("readonly", "");
    ta.style.position = "fixed";
    ta.style.left = "-9999px";
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand("copy"); } catch (e) {}
    ta.remove();
  }

  var number = document.querySelector('input[name="number"]');
  if (number) {
    number.addEventListener("input", function () {
      var digits = number.value.replace(/\D/g, "").slice(0, 16);
      var parts = digits.match(/.{1,4}/g);
      number.value = parts ? parts.join(" ") : "";
    });
  }
})();

package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"

	"shy/server/internal/config"
	"shy/server/internal/httpapi"
	"shy/server/internal/neatlogs"
	"shy/server/internal/store"
	"shy/server/internal/version"
)

func main() {
	if len(os.Args) > 1 {
		usage()
		if os.Args[1] == "-h" || os.Args[1] == "--help" {
			os.Exit(0)
		}
		os.Exit(2)
	}
	slog.SetDefault(slog.New(slog.NewTextHandler(os.Stderr, nil)))

	cfg, err := config.FromEnv()
	if err != nil {
		slog.Error("config", "err", err)
		os.Exit(1)
	}
	if strings.HasPrefix(cfg.PublicURL, "https://") && !cfg.CookieSecure {
		slog.Warn("SHY_PUBLIC_URL is https but SHY_COOKIE_SECURE is off; the browser will not keep the session cookie")
	}

	st, err := store.Open(cfg.DBPath)
	if err != nil {
		slog.Error("database", "err", err)
		os.Exit(1)
	}
	defer st.Close()

	var fwd neatlogs.Forwarder = neatlogs.Disabled{}
	mode := "store-only"
	if cfg.NeatlogsAPIKey != "" {
		fwd = &neatlogs.Client{IngestURL: cfg.NeatlogsIngestURL, APIKey: cfg.NeatlogsAPIKey}
		mode = "forwarding"
	} else {
		slog.Warn("SHY_NEATLOGS_API_KEY is unset; traces are stored and not forwarded")
	}

	app, err := httpapi.New(httpapi.Options{Config: cfg, Store: st, Forward: fwd})
	if err != nil {
		slog.Error("http", "err", err)
		os.Exit(1)
	}

	srv := &http.Server{
		Addr:              cfg.Addr,
		Handler:           app.Handler(),
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       60 * time.Second,
		WriteTimeout:      60 * time.Second,
		IdleTimeout:       120 * time.Second,
		MaxHeaderBytes:    1 << 16,
	}
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	go func() {
		<-ctx.Done()
		shut, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		_ = srv.Shutdown(shut)
	}()

	slog.Info("listening", "addr", cfg.Addr, "db", cfg.DBPath, "mode", mode, "version", version.Version)
	if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
		slog.Error("server", "err", err)
		os.Exit(1)
	}
}

func usage() {
	fmt.Fprintf(os.Stderr, `shyd %s — collect shy traces and forward them to Neatlogs.

Listens on SHY_HTTP_ADDR (default :8080). The SQLite file is SHY_DB_PATH (default shy.db).

Point shy at this server with an install key from the dashboard:

  export NEATLOGS_INGEST_URL=http://127.0.0.1:8080
  export NEATLOGS_API_KEY=shy_...

Environment:
  SHY_HTTP_ADDR              listen address (default :8080)
  SHY_DB_PATH                SQLite file (default shy.db)
  SHY_PUBLIC_URL             base URL shown in the dashboard
  SHY_NEATLOGS_API_KEY       project or write key used to forward traces
  SHY_NEATLOGS_PROJECT_NAME  dashboard project name; required for nlw_ write keys
  SHY_NEATLOGS_INGEST_URL    default https://ingest.neatlogs.com
  SHY_COOKIE_SECURE          1 when the dashboard is served over HTTPS
  SHY_TRUST_PROXY            1 to rate-limit using X-Forwarded-For
  SHY_BODY_LIMIT             max trace body in bytes (default 8388608, max 52428800)
`, version.Version)
}

