package store

import (
	"bytes"
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func testOpen(t *testing.T) *Store {
	t.Helper()
	s, err := Open(filepath.Join(t.TempDir(), "shy.db"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { s.Close() })
	return s
}

func TestWALAndForeignKeys(t *testing.T) {
	s := testOpen(t)
	var mode string
	if err := s.db.QueryRow("PRAGMA journal_mode").Scan(&mode); err != nil {
		t.Fatal(err)
	}
	if !strings.EqualFold(mode, "wal") {
		t.Fatalf("journal_mode %s", mode)
	}
	var fk int
	if err := s.db.QueryRow("PRAGMA foreign_keys").Scan(&fk); err != nil {
		t.Fatal(err)
	}
	if fk != 1 {
		t.Fatalf("foreign_keys %d", fk)
	}
	_, err := s.db.Exec(`INSERT INTO installs(account_id, name, key_hash, key_prefix, created_at) VALUES (999, 'x', 'h', 'p', 't')`)
	if err == nil {
		t.Fatal("expected foreign key failure")
	}
}

func TestSecretsAreHashed(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "shy.db")
	s, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	ctx := context.Background()
	acc, rawSession, err := s.CreateAccount(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if len(acc.Number) != 16 {
		t.Fatalf("number %q", acc.Number)
	}
	inst, key, err := s.CreateInstall(ctx, acc.ID, "laptop")
	if err != nil {
		t.Fatal(err)
	}
	var hash, prefix string
	if err := s.db.QueryRow(`SELECT key_hash, key_prefix FROM installs WHERE id = ?`, inst.ID).Scan(&hash, &prefix); err != nil {
		t.Fatal(err)
	}
	if hash != hashSecret(key) {
		t.Fatal("key hash mismatch")
	}
	if strings.Contains(hash, key) || !strings.HasPrefix(key, prefix) {
		t.Fatalf("hash %s prefix %s", hash, prefix)
	}
	got, gotAcc, err := s.InstallByKey(ctx, key)
	if err != nil || got.ID != inst.ID || gotAcc.Number != acc.Number {
		t.Fatalf("lookup: %+v %+v %v", got, gotAcc, err)
	}
	if _, _, err := s.InstallByKey(ctx, key+"nope"); err != ErrNotFound {
		t.Fatalf("bad key: %v", err)
	}
	if err := s.RevokeInstall(ctx, acc.ID, inst.ID); err != nil {
		t.Fatal(err)
	}
	if _, _, err := s.InstallByKey(ctx, key); err != ErrNotFound {
		t.Fatalf("revoked key: %v", err)
	}

	if _, err := s.db.Exec("PRAGMA wal_checkpoint(TRUNCATE)"); err != nil {
		t.Fatal(err)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}
	for _, name := range []string{path, path + "-wal"} {
		b, err := os.ReadFile(name)
		if err != nil {
			if os.IsNotExist(err) && strings.HasSuffix(name, "-wal") {
				continue
			}
			t.Fatal(err)
		}
		if bytes.Contains(b, []byte(key)) {
			t.Fatalf("plaintext api key in %s", name)
		}
		if bytes.Contains(b, []byte(rawSession)) {
			t.Fatalf("session token in %s", name)
		}
	}
}

func TestUniqueAccountNumber(t *testing.T) {
	s := testOpen(t)
	acc, _, err := s.CreateAccount(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	_, err = s.db.Exec(`INSERT INTO accounts(number, created_at, status) VALUES (?, 't', 'active')`, acc.Number)
	if err == nil {
		t.Fatal("expected unique violation")
	}
	if !isConstraint(err) {
		t.Fatalf("not a constraint error: %T %v", err, err)
	}
}

func TestFlashOnce(t *testing.T) {
	s := testOpen(t)
	ctx := context.Background()
	_, raw, err := s.CreateAccount(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.SetFlash(ctx, raw, Flash{Key: "shy_secret", InstallName: "laptop"}); err != nil {
		t.Fatal(err)
	}
	f, err := s.TakeFlash(ctx, raw)
	if err != nil || f.Key != "shy_secret" || f.InstallName != "laptop" {
		t.Fatalf("%+v %v", f, err)
	}
	f, err = s.TakeFlash(ctx, raw)
	if err != nil || f.Key != "" {
		t.Fatalf("second take %+v %v", f, err)
	}
}

package trace

import (
	"encoding/json"
	"strings"
	"testing"
)

func TestPrepareRewritesIdentity(t *testing.T) {
	raw := []byte(`{
		"name": " chat-turn ",
		"project": "evil",
		"trace_id": "nope",
		"status": "ok",
		"input": "hello",
		"attributes": {"neatlogs.end_user.id": "spoof", "neatlogs.session.id": "sess-1"},
		"children": [{
			"kind": "AGENT",
			"span_id": "abc",
			"parent_span_id": "def",
			"children": [
				{"kind": "LLM", "tokens": {"prompt": 10, "completion": 4, "total": 14}},
				{"kind": "llm", "tokens": {"prompt": 3, "completion": 1}}
			]
		}]
	}`)
	out, meta, err := Prepare(raw, "1111222233334444", 7, "laptop", "ignored", false)
	if err != nil {
		t.Fatal(err)
	}
	if meta.Workflow != "chat-turn" || meta.Status != "OK" || meta.SessionID != "sess-1" {
		t.Fatalf("%+v", meta)
	}
	if meta.PromptTokens != 13 || meta.CompletionTokens != 5 || meta.Spans != 4 {
		t.Fatalf("tokens/spans %+v", meta)
	}
	if meta.InputPreview != "hello" {
		t.Fatal(meta.InputPreview)
	}
	var root map[string]any
	if err := json.Unmarshal(out, &root); err != nil {
		t.Fatal(err)
	}
	if _, ok := root["project"]; ok {
		t.Fatal("project key should be removed for a project api key")
	}
	if _, ok := root["trace_id"]; ok {
		t.Fatal("trace_id should be stripped")
	}
	attrs := root["attributes"].(map[string]any)
	if attrs["neatlogs.end_user.id"] != "1111222233334444" {
		t.Fatal(attrs["neatlogs.end_user.id"])
	}
	metaStr, ok := attrs["neatlogs.end_user.metadata"].(string)
	if !ok || !strings.Contains(metaStr, `"install":"laptop"`) || !strings.Contains(metaStr, `"install_id":7`) {
		t.Fatalf("metadata %#v", attrs["neatlogs.end_user.metadata"])
	}
	kids := root["children"].([]any)
	child := kids[0].(map[string]any)
	if _, ok := child["span_id"]; ok {
		t.Fatal("child span_id remains")
	}
}

func TestPrepareWriteKeySetsProject(t *testing.T) {
	out, meta, err := Prepare([]byte(`{"name":"run","status":"ERROR","project":"evil"}`), "1", 1, "box", "demo", true)
	if err != nil {
		t.Fatal(err)
	}
	if meta.Status != "ERROR" {
		t.Fatal(meta.Status)
	}
	var root map[string]any
	if err := json.Unmarshal(out, &root); err != nil {
		t.Fatal(err)
	}
	if root["project"] != "demo" {
		t.Fatalf("project %v", root["project"])
	}
	if root["kind"] != "WORKFLOW" {
		t.Fatal(root["kind"])
	}
}

func TestPrepareRejects(t *testing.T) {
	cases := []string{
		``,
		`[]`,
		`{"status":"OK"}`,
		`{"name":"x"} extra`,
		`{"name":"x","children":{}}`,
	}
	for _, c := range cases {
		if _, _, err := Prepare([]byte(c), "1", 1, "n", "", false); err == nil {
			t.Fatalf("accepted %s", c)
		}
	}
}

func TestPrepareTooDeep(t *testing.T) {
	var b strings.Builder
	b.WriteString(`{"name":"deep"`)
	for i := 0; i < 80; i++ {
		b.WriteString(`,"children":[{"name":"n"`)
	}
	for i := 0; i < 81; i++ {
		b.WriteString(`}`)
	}
	_, _, err := Prepare([]byte(b.String()), "1", 1, "n", "", false)
	if err == nil || !strings.Contains(err.Error(), "nested") {
		t.Fatal(err)
	}
}

package neatlogs

import (
	"context"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestForward(t *testing.T) {
	var gotKey, gotPath string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotKey = r.Header.Get("x-api-key")
		gotPath = r.URL.Path
		w.Header().Set("Content-Type", "application/json")
		io.WriteString(w, `{"success":true,"trace_id":"abc123","spans":2}`)
	}))
	defer srv.Close()

	c := &Client{IngestURL: srv.URL + "/", APIKey: "secret"}
	id, spans, err := c.Forward(context.Background(), []byte(`{"name":"x"}`))
	if err != nil {
		t.Fatal(err)
	}
	if id != "abc123" || spans != 2 {
		t.Fatalf("id %s spans %d", id, spans)
	}
	if gotKey != "secret" || gotPath != "/v1/trace" {
		t.Fatalf("key %q path %q", gotKey, gotPath)
	}
}

func TestForwardDoesNotFollowRedirect(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, "https://example.invalid/steal", http.StatusFound)
	}))
	defer srv.Close()
	c := &Client{IngestURL: srv.URL, APIKey: "secret"}
	_, _, err := c.Forward(context.Background(), []byte(`{}`))
	if err == nil || !strings.Contains(err.Error(), "302") {
		t.Fatal(err)
	}
}

func TestDisabled(t *testing.T) {
	_, _, err := Disabled{}.Forward(context.Background(), []byte(`{}`))
	if err != ErrNotConfigured {
		t.Fatal(err)
	}
}

