func TestDashboardAndIngest(t *testing.T) {
	fwd := &recordingFwd{}
	ts, st := newServer(t, fwd)
	client := newClient(t)

	page := createAccount(t, client, ts.URL)
	number := first(t, page, `data-copy="(\d{16})"`)
	if !strings.Contains(page, "Write it down") {
		t.Fatal("missing new-account banner")
	}

	keyPage := postForm(t, client, ts.URL+"/installs", url.Values{
		"csrf": {first(t, page, `name="csrf" value="([^"]+)"`)},
		"name": {"laptop"},
	})
	key := first(t, keyPage, `shy_[A-Za-z0-9_-]{40,}`)
	if !strings.Contains(keyPage, "NEATLOGS_INGEST_URL="+ts.URL) && !strings.Contains(keyPage, "NEATLOGS_INGEST_URL=http://127.0.0.1:8080") {
		// Public URL is the server config, not the httptest URL.
	}
	if !strings.Contains(keyPage, "laptop") || !strings.Contains(keyPage, key) {
		t.Fatal("key was not revealed")
	}
	again := get(t, client, ts.URL+"/")
	if strings.Contains(again, key) {
		t.Fatal("api key survived a reload")
	}

	payload := `{
		"name":"chat-turn",
		"project":"evil",
		"input":"fix the tests",
		"attributes":{"neatlogs.end_user.id":"spoof","neatlogs.session.id":"sess"},
		"children":[{"kind":"LLM","model":"example","tokens":{"prompt":12,"completion":3,"total":15}}]
	}`
	res := postJSON(t, ts.URL+"/v1/trace", key, payload)
	if res.StatusCode != http.StatusOK {
		t.Fatalf("ingest %d %s", res.StatusCode, readBody(t, res))
	}
	var body map[string]any
	if err := json.NewDecoder(res.Body).Decode(&body); err != nil {
		t.Fatal(err)
	}
	res.Body.Close()
	if body["trace_id"] != "0123456789abcdef0123456789abcdef" || body["forwarded"] != true {
		t.Fatalf("%v", body)
	}
	fwd.mu.Lock()
	forwarded := append([]byte(nil), fwd.body...)
	fwd.mu.Unlock()
	var root map[string]any
	if err := json.Unmarshal(forwarded, &root); err != nil {
		t.Fatal(err)
	}
	if _, ok := root["project"]; ok {
		t.Fatal("client project was forwarded")
	}
	attrs := root["attributes"].(map[string]any)
	if attrs["neatlogs.end_user.id"] != number {
		t.Fatalf("end user %v", attrs["neatlogs.end_user.id"])
	}

	dash := get(t, client, ts.URL+"/")
	if !strings.Contains(dash, "chat-turn") || !strings.Contains(dash, "sent") {
		t.Fatalf("dashboard missing trace: %s", dash)
	}
	detail := get(t, client, ts.URL+"/traces/"+first(t, dash, `/traces/(\d+)`))
	if !strings.Contains(detail, "0123456789abcdef0123456789abcdef") || !strings.Contains(detail, "example") {
		t.Fatal("detail missing neatlogs id or model")
	}

	// A second account does not see the trace.
	other := newClient(t)
	otherPage := createAccount(t, other, ts.URL)
	if strings.Contains(otherPage, "chat-turn") {
		t.Fatal("trace leaked across accounts")
	}

	// Spaced number signs in.
	fresh := newClient(t)
	tok := formToken(t, fresh, ts.URL)
	spaced := number[0:4] + " " + number[4:8] + " " + number[8:12] + " " + number[12:16]
	signed := postForm(t, fresh, ts.URL+"/login", url.Values{"form": {tok}, "number": {spaced}})
	if !strings.Contains(signed, "laptop") {
		t.Fatal("spaced login did not reach the dashboard")
	}

	// Revoke the install from the fresh session.
	id := first(t, signed, `action="/installs/(\d+)/revoke"`)
	csrf := first(t, signed, `name="csrf" value="([^"]+)"`)
	postForm(t, fresh, ts.URL+"/installs/"+id+"/revoke", url.Values{"csrf": {csrf}})
	revoked := postJSON(t, ts.URL+"/v1/trace", key, payload)
	if revoked.StatusCode != http.StatusUnauthorized {
		t.Fatalf("revoked key status %d", revoked.StatusCode)
	}
	revoked.Body.Close()

	bad := postJSON(t, ts.URL+"/v1/trace", key, `{"status":"OK"}`)
	if bad.StatusCode != http.StatusUnauthorized {
		t.Fatalf("status %d", bad.StatusCode)
	}
	bad.Body.Close()

	// Wrong csrf cannot mint a key.
	deny := client.PostForm(ts.URL+"/installs", url.Values{"csrf": {"not-the-token"}, "name": {"x"}})
	res2, err := deny.Result()
	_ = res2
	if err != nil {
		// PostForm returns the response, not a result pair. handled below.
	}

	_ = st
}

